);

create table public.direct_messages (
  id uuid default gen_random_uuid() not null,
  sender_id uuid not null,
  receiver_id uuid not null,
  content text not null,
  reply_to_id uuid,
  file_attachment jsonb,
  created_at timestamp with time zone default now() not null,
  edited boolean default false,
  pinned boolean default false not null
);

create table public.email_tickets (
  id uuid default gen_random_uuid() not null,
  ticket_token character varying(64) not null,
  recipient_email character varying(255) not null,
  subject character varying(255) not null,
  gmail_message_id character varying(100),
  gmail_thread_id character varying(100),
  status character varying(30) default 'SENT'::character varying,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now()
);

create table public.invitations (
  id uuid default gen_random_uuid() not null,
  email text not null,
