);

create table public.notification_queue (
  id uuid default gen_random_uuid() not null,
  organization_id uuid,
  recipient_email text not null,
  notification notification_type not null,
  payload jsonb default '{}'::jsonb not null,
  status notification_status default 'pending'::notification_status not null,
  attempts integer default 0 not null,
  max_attempts integer default 3 not null,
  last_error text,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  next_retry_at timestamp with time zone default timezone('utc'::text, now()),
  processed_at timestamp with time zone
);

create table public.notifications (
  id uuid default gen_random_uuid() not null,
  user_id uuid not null,
  type text not null,
  reference_type text not null,
  reference_id uuid not null,
  body text not null,
  read_at timestamp with time zone,
  created_at timestamp with time zone default now() not null
);

create table public.org_feed_items (
  id uuid default gen_random_uuid() not null,
  organization_id uuid not null,
  team_space_id uuid,
