  created_at timestamp with time zone default now() not null
);

create table public.project_files (
  id uuid default gen_random_uuid() not null,
  project_id uuid,
  name text not null,
  type text,
  size bigint,
  path text not null,
  url text,
  created_at timestamp with time zone default now(),
  uploaded_by text,
  task_id uuid
);

create table public.project_members (
  id uuid default gen_random_uuid() not null,
  project_id uuid,
  user_id uuid,
  created_at timestamp with time zone default now()
);

create table public.project_spaces (
  id uuid default gen_random_uuid() not null,
  team_space_id uuid not null,
  name text not null,
  status text default 'active'::text not null,
  created_at timestamp with time zone default now() not null,
  search_vector tsvector generated always as (to_tsvector('english'::regconfig, COALESCE(name, ''::text))) stored,
  team_lead uuid default gen_random_uuid()
);

create table public.tasks (
  id uuid default gen_random_uuid() not null,
  organization_id uuid not null,
  project_id uuid,
  milestone_id uuid,
  title text not null,
  description text,
  status text default 'todo'::text not null,
  priority text,
  due_date date,
  assignee_id uuid,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  parent_task_id uuid,
  search_vector tsvector generated always as ((setweight(to_tsvector('english'::regconfig, COALESCE(title, ''::text)), 'A'::"char") || setweight(to_tsvector('english'::regconfig, COALESCE(description, ''::text)), 'B'::"char"))) stored,
  sub_tasks text,
  column_id uuid
);

create table public.team_space_stats (
  team_space_id uuid not null,
  open_tasks integer default 0 not null,
  in_progress integer default 0 not null,
  done_tasks integer default 0 not null,
  active_projects integer default 0 not null,
  updated_at timestamp with time zone default now() not null,
  overdue integer default 0
);

create table public.team_spaces (
  id uuid default gen_random_uuid() not null,
  organization_id uuid not null,
  name text not null,
  created_at timestamp with time zone default now() not null,
  description text
);

create table public.users (
  id uuid not null,
  organization_id uuid,
  email text not null,
  name text not null,
  auth_provider text default 'email'::text not null,
  created_at timestamp with time zone default now() not null,
  search_vector tsvector generated always as (to_tsvector('english'::regconfig, ((COALESCE(name, ''::text) || ' '::text) || COALESCE(email, ''::text)))) stored,
  description text
);

