AS $function$
  select case
    when p_team_space_id is not null then (select organization_id from team_spaces where id = p_team_space_id)
    else (select organization_id from users where id = p_user_id)
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.memberships_log_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    insert into activity_log (entity_type, entity_id, actor_id, action, prior_state, new_state)
    values ('membership', new.id, auth.uid(), 'created', null, to_jsonb(new));
  elsif tg_op = 'UPDATE' then
    insert into activity_log (entity_type, entity_id, actor_id, action, prior_state, new_state)
    values ('membership', new.id, auth.uid(), 'updated', to_jsonb(old), to_jsonb(new));
  elsif tg_op = 'DELETE' then
    insert into activity_log (entity_type, entity_id, actor_id, action, prior_state, new_state)
    values ('membership', old.id, auth.uid(), 'removed', to_jsonb(old), null);
  end if;
  return coalesce(new, old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mfa_satisfied()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2'
      or not exists (
        select 1 from auth.mfa_factors f
        where f.user_id = auth.uid() and f.status = 'verified'
      )
      or public.is_trusted_device();
$function$
;

