CREATE OR REPLACE FUNCTION public.tasks_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_name text;
begin
  select name into v_actor_name from users where id = auth.uid();

  if tg_op = 'INSERT' then
    if new.assignee_id is not null and new.assignee_id != coalesce(new.created_by, '00000000-0000-0000-0000-000000000000'::uuid) then
      perform notify_user(new.assignee_id, 'assignment', 'task', new.id,
        coalesce(v_actor_name, 'Someone') || ' assigned you to "' || new.title || '"');
    end if;
  elsif tg_op = 'UPDATE' then
    if new.assignee_id is distinct from old.assignee_id and new.assignee_id is not null then
      perform notify_user(new.assignee_id, 'assignment', 'task', new.id,
        coalesce(v_actor_name, 'Someone') || ' assigned you to "' || new.title || '"');
    end if;
    if new.status is distinct from old.status and old.created_by is not null then
      perform notify_user(old.created_by, 'status_change', 'task', new.id,
        '"' || new.title || '" moved to ' || new.status);
    end if;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tasks_refresh_stats()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_team_space_id uuid;
begin
  select team_space_id into v_team_space_id from project_spaces
    where id = coalesce(new.project_id, old.project_id);
  if v_team_space_id is not null then
    perform refresh_team_space_stats(v_team_space_id);
  end if;
  return coalesce(new, old);
end;
$function$
;

