CREATE OR REPLACE FUNCTION public.toggle_dm_pin(p_message_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_pinned boolean;
begin
  update public.direct_messages
     set pinned = not pinned
   where id = p_message_id
     and auth.uid() in (sender_id, receiver_id)
  returning pinned into v_pinned;

  if v_pinned is null then
    raise exception 'Message not found';
  end if;
  return v_pinned;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trust_this_device(p_user_agent text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
begin
  if auth.uid() is null or coalesce(auth.jwt() ->> 'aal', 'aal1') <> 'aal2' then
    raise exception 'Enter your two-factor code first';
  end if;

  delete from public.mfa_trusted_devices where user_id = auth.uid() and expires_at <= now();

  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.mfa_trusted_devices (user_id, token_hash, user_agent, expires_at)
  values (
    auth.uid(),
    encode(extensions.digest(v_token, 'sha256'), 'hex'),
    left(p_user_agent, 300),
    now() + interval '7 days'
  );
  return v_token;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.users_guard_protected_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('authenticated', 'anon') and (
       new.id is distinct from old.id
    or new.organization_id is distinct from old.organization_id
    or new.email is distinct from old.email
    or new.auth_provider is distinct from old.auth_provider
  ) then
    raise exception 'Not allowed to change id, organization, email or auth provider';
  end if;
  return new;
end;
$function$
;

