create policy project_members_insert on public.project_members as permissive for insert to authenticated
  with check ((can_manage_project(project_id) AND (EXISTS ( SELECT 1
   FROM users u
  WHERE ((u.id = project_members.user_id) AND (u.organization_id = current_org_id()))))));

create policy project_members_select on public.project_members as permissive for select to authenticated
  using ((has_project_access(project_id) OR can_manage_project(project_id)));

create policy mfa_required on public.project_spaces as restrictive for all to authenticated
  using (mfa_satisfied())
  with check (mfa_satisfied());

create policy project_spaces_delete on public.project_spaces as permissive for delete to authenticated
  using ((team_role_at_least(team_space_id, 'team_lead'::membership_role) OR is_admin_of_org(team_space_org(team_space_id))));

create policy project_spaces_insert on public.project_spaces as permissive for insert to public
  with check ((team_role_at_least(team_space_id, 'team_lead'::membership_role) OR is_admin_of_org(team_space_org(team_space_id))));

create policy project_spaces_select on public.project_spaces as permissive for select to public
  using ((has_team_access(team_space_id) OR is_project_member(id) OR is_admin_of_org(team_space_org(team_space_id))));

create policy project_spaces_update on public.project_spaces as permissive for update to public
  using ((team_role_at_least(team_space_id, 'team_lead'::membership_role) OR is_admin_of_org(team_space_org(team_space_id))))
  with check ((team_role_at_least(team_space_id, 'team_lead'::membership_role) OR is_admin_of_org(team_space_org(team_space_id))));

create policy mfa_required on public.tasks as restrictive for all to authenticated
  using (mfa_satisfied())
  with check (mfa_satisfied());

create policy tasks_delete on public.tasks as permissive for delete to authenticated
  using (((created_by = auth.uid()) OR ((project_id IS NULL) AND is_admin_of_org(organization_id)) OR ((project_id IS NOT NULL) AND can_manage_project(project_id))));

create policy tasks_insert on public.tasks as permissive for insert to public
  with check (((organization_id = current_org_id()) AND ((project_id IS NULL) OR can_edit_project(project_id))));

create policy tasks_select on public.tasks as permissive for select to public
  using ((((project_id IS NULL) AND (organization_id = current_org_id())) OR ((project_id IS NOT NULL) AND has_project_access(project_id))));

create policy tasks_update on public.tasks as permissive for update to public
  using ((((project_id IS NULL) AND (organization_id = current_org_id())) OR ((project_id IS NOT NULL) AND can_edit_project(project_id))))
  with check (((organization_id = current_org_id()) AND ((project_id IS NULL) OR can_edit_project(project_id))));

create policy mfa_required on public.team_space_stats as restrictive for all to authenticated
  using (mfa_satisfied())
  with check (mfa_satisfied());

create policy team_space_stats_select on public.team_space_stats as permissive for select to public
  using (has_team_access(team_space_id));

create policy mfa_required on public.team_spaces as restrictive for all to authenticated
  using (mfa_satisfied())
  with check (mfa_satisfied());

create policy team_spaces_delete_admin on public.team_spaces as permissive for delete to authenticated
  using (((organization_id = current_org_id()) AND is_org_admin()));

create policy team_spaces_insert_admin on public.team_spaces as permissive for insert to public
  with check (((organization_id = current_org_id()) AND is_org_admin()));

create policy team_spaces_select on public.team_spaces as permissive for select to public
  using (((organization_id = current_org_id()) AND (has_team_access(id) OR is_org_admin() OR is_member_of_project_in_team(id))));

create policy team_spaces_update_admin on public.team_spaces as permissive for update to public
  using (((organization_id = current_org_id()) AND is_org_admin()))
  with check (((organization_id = current_org_id()) AND is_org_admin()));

create policy mfa_required on public.users as restrictive for all to authenticated
  using (mfa_satisfied())
  with check (mfa_satisfied());

create policy users_insert_self on public.users as permissive for insert to authenticated
  with check (((id = auth.uid()) AND (organization_id IS NULL)));

create policy users_select_same_org on public.users as permissive for select to public
  using (((id = auth.uid()) OR ((organization_id IS NOT NULL) AND (organization_id = current_org_id()))));

create policy users_update_self on public.users as permissive for update to public
  using ((id = auth.uid()))
  with check ((id = auth.uid()));

create policy chat_attachments_objects_delete on storage.objects as permissive for delete to authenticated
  using (((bucket_id = 'chat-attachments'::text) AND (EXISTS ( SELECT 1
   FROM messages m
  WHERE ((m.id = storage_path_uuid(objects.name, 2)) AND (m.user_id = auth.uid()))))));

create policy chat_attachments_objects_insert on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'chat-attachments'::text) AND (EXISTS ( SELECT 1
   FROM messages m
  WHERE ((m.id = storage_path_uuid(objects.name, 2)) AND (m.channel_id = storage_path_uuid(objects.name, 1)) AND (m.user_id = auth.uid()))))));

create policy chat_attachments_objects_select on storage.objects as permissive for select to authenticated
  using (((bucket_id = 'chat-attachments'::text) AND can_see_channel(storage_path_uuid(name, 1))));

create policy mfa_required on storage.objects as restrictive for all to authenticated
  using (mfa_satisfied())
  with check (mfa_satisfied());

create policy project_files_objects_delete on storage.objects as permissive for delete to authenticated
  using (((bucket_id = 'project-files'::text) AND can_edit_project(project_id_from_storage_path(name))));

create policy project_files_objects_insert on storage.objects as permissive for insert to authenticated
  with check (((bucket_id = 'project-files'::text) AND can_edit_project(project_id_from_storage_path(name))));

create policy project_files_objects_select on storage.objects as permissive for select to authenticated
  using (((bucket_id = 'project-files'::text) AND has_project_access(project_id_from_storage_path(name))));

